def compute(vars):
    values = [
        vars["v1"],
        vars["v2"],
        vars["v3"],
        vars["v4"],
        vars["v5"],
    ]
    threshold = 50000
    qualifying_years = [value for value in values if value > threshold]
    result = len(qualifying_years)

    return {
        "value": result,
        "trace": {
            "values": values,
            "threshold": threshold,
            "qualifying_years": qualifying_years,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "count",
            },
        },
    }
